INSERT INTO public.interview_questions (id, session_id, order_index, question_type, content, difficulty, skill_tag, time_limit_seconds, ai_generated) VALUES ('3a797472-23cd-4323-ba7b-254c76b647b6', '7b69146a-e97c-43cc-9ef7-6caa0d7f1392', 1, 'technical', 'Bạn hãy mô tả cách bạn xử lý giao dịch (transactions) và tối ưu truy cập PostgreSQL trong một ứng dụng Spring Boot sản xuất. Nêu rõ cấu hình (ví dụ: @Transactional propagation/isolation), quản lý connection pool, xử lý batch inserts/updates, và cách debug/giải quyết vấn đề deadlock hoặc slow queries. Nếu có thể, đưa ví dụ ngắn về cấu hình hoặc đoạn mã minh họa.', 'medium', 'Spring Boot', 180, true);
